package in.chinatech.phoneassistant;
import java.io.*;import java.util.*;
/** Original task identity/scope negatives; independent of Android storage and live API acceptance. */
public final class PhoneRecoveryCoreTest {
 static int checks;interface Work{void run()throws Exception;}static void ok(boolean b,String name){checks++;if(!b)throw new AssertionError(name);}static void reject(Work run,String name)throws Exception {boolean failed=false;try{run.run();}catch(IOException e){failed=true;}ok(failed,name);}
 public static void main(String[] args)throws Exception {
  String receiver=UUID.randomUUID().toString(),sender=UUID.randomUUID().toString(),rjob=UUID.randomUUID().toString(),sjob=UUID.randomUUID().toString(),pin="a".repeat(64),other="b".repeat(64);PhoneGateCore.Plan plan=new PhoneGateCore.Plan(String.join("|","CTPA5P",ProtocolCore.token(16),receiver,sender,rjob,sjob,pin,other,ProtocolCore.token(16),pin,pin,"2","65537"));
  for(boolean receiving:new boolean[]{true,false}){String installation=receiving?receiver:sender;Map<String,Object> task=new LinkedHashMap<>();task.put("id",UUID.randomUUID().toString());task.put("job",receiving?rjob:sjob);task.put("receiving",receiving);task.put("plan",plan.encode());task.put("pin",receiving?pin:other);task.put("tls","ctpa-session-"+ProtocolCore.token(16));task.put("version",PhoneGateCore.VERSION);task.put("release",PhoneGateCore.RELEASE);task.put("startRequest",UUID.randomUUID().toString());task.put("startNonce",PhoneGateCore.b64(ProtocolCore.random(32)));
   ok(PhoneRecoveryCore.identity(task,installation).scope().equals(plan.scope()),"own original role binding");PhoneRecoveryCore.frozen(task,new HashMap<>(task));checks++;ok(PhoneRecoveryCore.canStartOriginal(task),"current release may seek fresh original admission only after website approval");Map<String,Object> legacy=new HashMap<>(task);legacy.put("release","phone-assistant-0.5.0");legacy.put("version","0.5.0-test");ok(PhoneRecoveryCore.identity(legacy,installation).scope().equals(plan.scope()),"original 0.5 task identity survives current 0.5.1 client");ok(!PhoneRecoveryCore.canStartOriginal(legacy),"old unregistered task cannot silently start on current release");
   for(String field:new String[]{"id","job","plan","receiving","version","release","tls","pin","startRequest","startNonce"}){Map<String,Object> tampered=new HashMap<>(task);tampered.put(field,field.equals("receiving")?!receiving:"changed");reject(()->PhoneRecoveryCore.frozen(task,tampered),"frozen "+field);}
   Map<String,Object> scope=new HashMap<>(task);scope.put("plan",plan.encode().replace("65537","65538"));reject(()->PhoneRecoveryCore.frozen(task,scope),"scope changes rejected before network");reject(()->PhoneRecoveryCore.identity(task,UUID.randomUUID().toString()),"cross instance");Map<String,Object> job=new HashMap<>(task);job.put("job",UUID.randomUUID().toString());reject(()->PhoneRecoveryCore.identity(job,installation),"job differs from original plan");Map<String,Object> tls=new HashMap<>(task);tls.put("tls","other-prefix-key");reject(()->PhoneRecoveryCore.identity(tls,installation),"foreign TLS alias");Map<String,Object> missing=new HashMap<>(task);missing.remove("startNonce");reject(()->PhoneRecoveryCore.identity(missing,installation),"half-saved request identity refused");Map<String,Object> retry=new HashMap<>(task);retry.put("admissionAttempt",true);retry.put("ownPermit","new original signed response");PhoneRecoveryCore.frozen(task,retry);checks++;Map<String,Object> cancelled=new HashMap<>(task);cancelled.put("terminal","cancelled");reject(()->PhoneRecoveryCore.frozen(cancelled,task),"cancellation cannot become pending");Map<String,Object> withPeer=new HashMap<>(task);withPeer.put("peerPermit","original");Map<String,Object> swapped=new HashMap<>(withPeer);swapped.put("peerPermit","replacement");reject(()->PhoneRecoveryCore.frozen(withPeer,swapped),"original peer grant preserved");
  }
  System.out.println("{\"suite\":\"phone-original-admission-recovery\",\"assertions\":"+checks+",\"androidOrLiveApiProof\":false}");
 }
}
